<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
import BlueMail from './BlueMail.vue';
import DojoIcon from './DojoIcon.vue';
import DojoReport from './DojoReport.vue';
const reportOpen=ref(false),reportRef=ref(null);
import BlueTickets from './BlueTickets.vue';
const archive=ref(false),archiveRef=ref(null),reader=ref(false),readerRef=ref(null),participants=ref(false),readerBatch=ref(false),selected=ref([]),roles=ref([]),rows=ref([]),revision=ref(null),busy=ref(false),error=ref(''),view=ref('daily'),month=ref(''),role=ref(''),source=ref('all');
const localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=localDate(new Date());
function shift(date,n){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return localDate(d)}
function monday(date){const d=new Date(date+'T12:00:00');return shift(date,-((d.getDay()+6)%7))}
const weekStart=ref(monday(today)),weekPage=ref(0),weekCap=ref(3),weekBox=ref(null),calendarRole=ref(''),resource=ref(''),detail=ref(null);
const baseRows=computed(()=>rows.value.filter(r=>(!role.value||r.role_id===role.value)&&(source.value==='all'||(source.value==='round'?r.type===400179:r.type===400175))));
const weekDates=computed(()=>Array.from({length:7},(_,i)=>shift(weekStart.value,i)));
const shownRoles=computed(()=>roles.value.filter(r=>(r.selected||rows.value.some(m=>m.role_id===r.id))&&(!role.value||r.id===role.value)));
const weekRoles=computed(()=>shownRoles.value.slice(weekPage.value*weekCap.value,(weekPage.value+1)*weekCap.value));
const maxPage=computed(()=>Math.max(1,Math.ceil(shownRoles.value.length/weekCap.value)));
function resources(list){const map=new Map();for(const row of list)for(const [id,n] of row.items)map.set(id,(map.get(id)||0)+n);return [...map].map(([id,n])=>({id,n,...label(id)})).sort((a,b)=>(a.id===490001?-1:b.id===490001?1:a.name.localeCompare(b.name,'zh-CN')||(a.stars||0)-(b.stars||0)));}
const resourceOptions=computed(()=>resources(rows.value));
function dayMails(id,date){return baseRows.value.filter(r=>r.role_id===id&&r.date===date)}
function dayItems(id,date){return resources(dayMails(id,date)).filter(r=>!resource.value||String(r.id)===resource.value)}
function weekItems(id){return resources(baseRows.value.filter(r=>r.role_id===id&&r.date>=weekStart.value&&r.date<=weekDates.value[6])).filter(r=>!resource.value||String(r.id)===resource.value)}
function itemText(r){return r.name+(r.stars?` ${r.stars}星`:'')+' × '+r.n.toLocaleString('zh-CN')}
const calendarMonth=computed(()=>month.value||today.slice(0,7));
const calendarDays=computed(()=>{const first=calendarMonth.value+'-01';const d=new Date(first+'T12:00:00');const offset=(d.getDay()+6)%7;const end=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();return [...Array(offset).fill(null),...Array.from({length:end},(_,i)=>shift(first,i))]});
const detailRows=computed(()=>detail.value?dayMails(detail.value.id,detail.value.date):[]);
const detailItems=computed(()=>resources(detailRows.value));
function openDay(id,date){detail.value={id,date,label:roles.value.find(r=>r.id===id)?.label||'历史角色'}}
let observer;
onMounted(()=>{observer=new ResizeObserver(entries=>{if(view.value!=='week')return;const h=weekBox.value?.querySelector('.dojo-week-wrap')?.clientHeight||entries[0].contentRect.height;weekCap.value=Math.max(1,Math.floor((h-66)/112));});if(weekBox.value)observer.observe(weekBox.value)});
onUnmounted(()=>observer?.disconnect());
watch([weekBox,view],()=>{if(weekBox.value)observer?.observe(weekBox.value)});
watch([role,weekCap],()=>{weekPage.value=0});
watch(month,()=>{weekPage.value=0;if(month.value)weekStart.value=monday(month.value+'-01')});
watch(shownRoles,list=>{if(!list.some(r=>r.id===calendarRole.value))calendarRole.value=list[0]?.id||'';weekPage.value=Math.min(weekPage.value,maxPage.value-1)},{immediate:true});
const filtered=computed(()=>baseRows.value.filter(r=>view.value==='week'?(r.date>=weekStart.value&&r.date<=weekDates.value[6]):(!month.value||r.date.startsWith(month.value))));
const catalog=computed(()=>Object.assign({},...rows.value.map(r=>r.item_meta||{})));
const names=computed(()=>Object.assign({},...rows.value.map(r=>r.item_names||{})));
function label(id){const info=catalog.value[id]||{};return {name:info.name||names.value[id]||'名称待识别',stars:info.stars||null,card:info.kind==='realm_card'||(info.name||names.value[id])==='太阴符咒'}}
const totals=computed(()=>{const m=new Map();for(const r of filtered.value)for(const [id,n] of r.items)m.set(id,(m.get(id)||0)+n);return [...m].map(([id,n])=>({id,n,...label(id)})).filter(r=>!resource.value||String(r.id)===resource.value).sort((a,b)=>a.name.localeCompare(b.name,'zh-CN')||(a.stars||0)-(b.stars||0));});
const days=computed(()=>{const m=new Map();for(const r of filtered.value){const key=r.role_id+'|'+r.date;if(!m.has(key))m.set(key,{key,date:r.date,label:r.label,count:0,items:new Map()});const d=m.get(key);d.count++;for(const [id,n] of r.items)d.items.set(id,(d.items.get(id)||0)+n);}return [...m.values()].sort((a,b)=>b.date.localeCompare(a.date)).map(d=>({...d,items:[...d.items].map(([id,n])=>({id,n,...label(id)})).filter(r=>!resource.value||String(r.id)===resource.value)}));});
const enrolled=computed(()=>roles.value.filter(r=>r.selected&&r.active).length);
const countRoles=computed(()=>new Set(filtered.value.map(r=>r.role_id)).size);
async function refresh(){busy.value=true;error.value='';try{const a=await window.pywebview.api.blue_mail('archives');if(!a.ok)throw Error(a.error);roles.value=a.data.roles;revision.value=a.data.revision;const b=await window.pywebview.api.blue_mail('records');if(!b.ok)throw Error(b.error);rows.value=b.data.filter(r=>r.type!==400175);}catch(e){error.value=e.message}finally{busy.value=false}}
function choose(){selected.value=roles.value.filter(r=>r.selected&&r.active).map(r=>r.id);participants.value=true}
async function saveSubjects(){busy.value=true;error.value='';try{const r=await window.pywebview.api.blue_records('subjects',{ids:selected.value,revision:revision.value});if(!r.ok)throw Error(r.error);roles.value=r.data.roles;revision.value=r.data.revision;participants.value=false;}catch(e){error.value=e.message}finally{busy.value=false}}
async function exportCsv(){busy.value=true;error.value='';try{const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const data=[['角色','日期（北京时间）','奖励类型','资源名称','星级','数量']];for(const r of filtered.value)for(const [id,n] of r.items){if(resource.value&&String(id)!==resource.value)continue;const x=label(id);data.push([r.label,r.date,r.type===400179?'场次奖励':'道馆奖励',x.name,x.stars??(x.card?'待识别':''),n]);}const r=await window.pywebview.api.blue_export({kind:'csv',filename:'道馆产出.csv',content:data.map(r=>r.map(cell).join(',')).join('\r\n')});if(!r.ok)throw Error(r.error)}catch(e){error.value=e.message}finally{busy.value=false}}
function canLeave(){if(reportOpen.value&&reportRef.value?.canLeave()===false)return false;reportOpen.value=false;detail.value=null;if(busy.value)return false;if(reader.value&&readerRef.value?.canLeave()===false)return false;if(archive.value&&archiveRef.value?.canLeave()===false)return false;return true}defineExpose({canLeave});onMounted(refresh);
</script>
<template><div class="dojo-page" v-if="!archive"><header class="dojo-header"><div><h1>道馆产出</h1><p>按角色和战斗日记录全部道馆资源，结界卡分星级统计。</p></div><div class="dojo-actions"><button @click="readerBatch=false;reader=true" :disabled="busy">读取单个窗口</button><button class="dojo-primary" @click="readerBatch=true;reader=true" :disabled="busy">一键读取全部</button><button @click="refresh" :disabled="busy">刷新</button><button @click="reportOpen=true" :disabled="busy">周报 / 月报</button><details class="dojo-more"><summary>更多</summary><div><button @click="exportCsv" :disabled="busy||!filtered.length">导出 CSV</button><button class="dojo-link" @click="archive=true">旧蓝票记录</button></div></details></div></header><p class="dojo-error" v-if="error" role="alert">{{error}}</p><section class="dojo-filter"><label>月份<input aria-label="产出月份" type="month" v-model="month"></label><button @click="month=''">全部日期</button><label>角色<select aria-label="产出角色" v-model="role"><option value="">全部角色</option><option v-for="r in roles.filter(r=>r.selected||rows.some(x=>x.role_id===r.id))" :key="r.id" :value="r.id">{{r.label}} · {{r.server}}</option></select></label><label>显示资源<select aria-label="显示资源" v-model="resource"><option value="">全部资源</option><option v-for="r in resourceOptions" :key="r.id" :value="String(r.id)">{{r.name}}{{r.stars?' · '+r.stars+'星':''}}</option></select></label><span>记录保存在本机</span></section><div class="dojo-summary">已记录 {{filtered.length}} 封奖励邮件 · {{countRoles}} 个角色 · {{totals.length}} 种资源（不同星级分开）</div><section class="dojo-panel"><nav class="dojo-tabs" aria-label="产出视图"><button v-for="t in [{id:'daily',name:'角色日报'},{id:'overview',name:'资源看板'},{id:'calendar',name:'月历'},{id:'detail',name:'邮件明细'}]" :key="t.id" :aria-pressed="view===t.id" :class="{active:view===t.id}" @click="view=t.id">{{t.name}}</button><small>邮件发送日即战斗日</small></nav><div class="dojo-week" v-if="view==='week'" ref="weekBox"><div class="dojo-week-tools"><b>{{weekStart}} — {{weekDates[6]}}</b><div><button @click="weekStart=shift(weekStart,-7)">上一周</button><button @click="weekStart=monday(today)">本周</button><button @click="weekStart=shift(weekStart,7)">下一周</button></div></div><div class="dojo-week-wrap"><table class="dojo-week-table"><thead><tr><th>角色 / 日期</th><th v-for="(date,i) in weekDates" :key="date">{{['周一','周二','周三','周四','周五','周六','周日'][i]}}<small>{{date.slice(5)}}</small></th><th>一周合计</th></tr></thead><tbody><tr v-for="r in weekRoles" :key="r.id"><th>{{r.label}}<small>{{r.server}}</small></th><td v-for="date in weekDates" :key="date"><button class="dojo-day-cell" :data-date="date" :class="{recorded:dayMails(r.id,date).length}" @click="openDay(r.id,date)" :title="dayItems(r.id,date).map(itemText).join('；')"><template v-if="dayMails(r.id,date).length"><span v-for="item in dayItems(r.id,date).slice(0,3)" :key="item.id"><i>{{item.name}}{{item.stars?' '+item.stars+'星':''}}</i><b>{{item.n.toLocaleString('zh-CN')}}</b></span><small>{{dayMails(r.id,date).length}} 封{{dayItems(r.id,date).length>3?' · 查看全部':''}}{{!dayItems(r.id,date).length?' · 无该资源':''}}</small></template><span class="dojo-unread" v-else>未记录</span></button></td><td><div class="dojo-week-total" :title="weekItems(r.id).map(itemText).join('；')"><span v-for="item in weekItems(r.id).slice(0,3)" :key="item.id">{{itemText(item)}}</span><small v-if="weekItems(r.id).length>3">更多资源见明细</small><span v-if="!weekItems(r.id).length">—</span></div></td></tr><tr v-if="!weekRoles.length"><td colspan="9" class="dojo-empty">先选择参与角色，再读取游戏邮件。</td></tr></tbody></table></div><footer class="dojo-week-pager"><span>共 {{shownRoles.length}} 个角色 · 第 {{weekPage+1}} / {{maxPage}} 页</span><div><button :disabled="!weekPage" @click="weekPage--">上一页</button><button :disabled="weekPage>=maxPage-1" @click="weekPage++">下一页</button></div></footer></div>
<div class="dojo-calendar" v-else-if="view==='calendar'"><div class="dojo-week-tools"><b>{{calendarMonth}} · 个人月历</b><label>角色 <select aria-label="月历角色" v-model="calendarRole"><option v-for="r in shownRoles" :key="r.id" :value="r.id">{{r.label}}</option></select></label></div><div class="dojo-calendar-grid" :style="{'--rows':Math.ceil(calendarDays.length/7)}"><strong v-for="day in ['周一','周二','周三','周四','周五','周六','周日']" :key="day">{{day}}</strong><template v-for="(date,index) in calendarDays" :key="index"><div v-if="!date"></div><button v-else class="dojo-calendar-cell" :data-date="date" :disabled="!calendarRole" :class="{recorded:dayMails(calendarRole,date).length}" @click="openDay(calendarRole,date)" :title="dayItems(calendarRole,date).map(itemText).join('；')"><b>{{Number(date.slice(-2))}}</b><span v-for="r in dayItems(calendarRole,date).slice(0,2)" :key="r.id">{{itemText(r)}}</span><small>{{dayMails(calendarRole,date).length?dayMails(calendarRole,date).length+' 封 · 点击查看':'未记录'}}</small></button></template></div></div>
<div class="dojo-scroll" v-else><div class="dojo-empty" v-if="!filtered.length"><h2>还没有道馆产出记录</h2><p>打开游戏后点击“一键读取全部”，自动建立独立角色档案。<br>未读取或缺少邮件不代表零产出。</p><button class="dojo-primary" @click="readerBatch=true;reader=true">开始读取</button></div><div class="dojo-resources" v-else-if="view==='overview'"><article v-for="r in totals" :key="r.id"><span><DojoIcon :id="r.id" />{{r.name}}</span><span class="dojo-stars" v-if="r.stars">{{'★'.repeat(r.stars)}} <small>{{r.stars}} 星</small></span><small v-else-if="r.card">星级待识别</small><strong>{{r.n.toLocaleString('zh-CN')}}</strong></article></div><div class="dojo-daily-layout" v-else-if="view==='daily'"><aside class="dojo-role-list" aria-label="日报角色"><button :class="{active:!role}" @click="role=''">全部角色</button><button v-for="r in roles.filter(r=>r.selected||rows.some(x=>x.role_id===r.id))" :key="r.id" :class="{active:role===r.id}" @click="role=r.id"><b>{{r.label}}</b><small>{{r.server}}</small></button></aside><div class="dojo-day-ledger"><article class="dojo-day-card" v-for="d in days" :key="d.key"><header><div><b>{{d.date}}</b><span>{{d.label}} · {{d.count}} 封奖励邮件</span></div><button @click="openDay(d.key.split('|')[0],d.date)">邮件明细</button></header><div class="dojo-day-resources"><div v-for="r in d.items.filter(x=>!x.card)" :key="r.id"><span><DojoIcon :id="r.id" />{{r.name}}</span><b>{{r.n.toLocaleString('zh-CN')}}</b></div></div><div class="dojo-day-cards" v-if="d.items.some(x=>x.card)"><span>结界卡</span><div v-for="r in d.items.filter(x=>x.card)" :key="r.id"><DojoIcon :id="r.id" /><span>{{r.name}} <i>{{r.stars?r.stars+' 星':'星级待识别'}}</i></span><b>{{r.n.toLocaleString('zh-CN')}}</b></div></div></article></div></div><table v-else><thead><tr><th>角色 / 时间（北京时间）</th><th>来源</th><th>全部奖励</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.scope+r.uid"><td>{{r.label}}<br>{{new Date(r.time*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</td><td>{{r.type===400179?'场次奖励':'道馆奖励'}}</td><td><span class="dojo-chip" v-for="(item,index) in r.items.filter(i=>!resource||String(i[0])===resource)" :key="index">{{label(item[0]).name}} <i v-if="label(item[0]).stars">{{label(item[0]).stars}} 星</i> × {{item[1]}}</span></td></tr></tbody></table></div></section><DojoReport v-if="reportOpen" ref="reportRef" :rows="rows" :roles="roles" :initial-role="role" :initial-date="month?month+'-01':weekStart" @close="reportOpen=false" /><BlueMail v-if="reader" ref="readerRef" :batch="readerBatch" @close="reader=false" @updated="refresh" /><Teleport to="body"><div class="dojo-subject-mask" v-if="detail" @click.self="detail=null"><section role="dialog" aria-label="当日道馆资源"><header><h2>{{detail.label}} · {{detail.date}}</h2><p>共 {{detailRows.length}} 封道馆奖励邮件</p></header><div class="dojo-detail-items"><p v-for="r in detailItems" :key="r.id">{{r.name}} <strong v-if="r.stars">{{r.stars}} 星</strong><b>{{r.n.toLocaleString('zh-CN')}}</b></p><p v-if="!detailRows.length">尚未记录当天邮件，不表示产出为零。</p></div><footer><button @click="detail=null">关闭</button></footer></section></div><div class="dojo-subject-mask" v-if="participants"><section role="dialog" aria-label="参与道馆记录的角色"><h2>参与道馆记录的角色</h2><p>沿用已有参与名单，移出名单会保留历史产出。</p><div class="dojo-subjects"><label v-for="r in roles.filter(r=>r.active)" :key="r.id"><input type="checkbox" v-model="selected" :value="r.id">{{r.label}} · {{r.server}}</label></div><p class="dojo-error" v-if="error">{{error}}</p><footer><button :disabled="busy" @click="participants=false">取消</button><button class="dojo-primary" :disabled="busy" @click="saveSubjects">保存名单</button></footer></section></div></Teleport></div><div class="dojo-archive" v-else><button @click="archiveRef?.canLeave()!==false&&(archive=false)">← 返回道馆产出</button><BlueTickets ref="archiveRef" /></div></template>
<style scoped>
.dojo-page{height:100%;display:flex;flex-direction:column;gap:16px;padding:22px;overflow:hidden;color:#3a372e;font:14px/1.5 "Microsoft YaHei UI","Microsoft YaHei",sans-serif}.dojo-header{display:flex;justify-content:space-between;gap:16px;align-items:center;flex:none}.dojo-header h1{font-size:25px;margin:0}.dojo-header p{margin:6px 0 0;color:#796b56;font-size:13px}.dojo-actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.dojo-page button,.dojo-subject-mask button,.dojo-archive>button{font:inherit;border:1px solid #ddceb7;background:#fffcf6;color:#70573c;padding:8px 13px;border-radius:6px;cursor:pointer}.dojo-page button:disabled{opacity:.5}.dojo-page .dojo-primary,.dojo-subject-mask .dojo-primary{background:#745b40;border-color:#745b40;color:white}.dojo-page .dojo-link{background:transparent;border-color:transparent;color:#8b7962}.dojo-filter{display:flex;gap:12px;align-items:end;padding:13px 16px;background:#eee7da;border:1px solid #e3d8c6;border-radius:8px;flex-wrap:wrap;flex:none}.dojo-filter label{display:flex;flex-direction:column;gap:5px;font-size:12px}.dojo-filter input,.dojo-filter select{font:14px "Microsoft YaHei UI",sans-serif;padding:7px 10px;border:1px solid #d8c8b0;border-radius:5px;background:#fffdf9;min-height:35px;max-width:240px}.dojo-filter>span{margin-left:auto;align-self:center;color:#796c5a;font-size:12px}.dojo-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;flex:none}.dojo-metrics>div{background:#fffcf7;border:1px solid #e0d5c3;border-radius:8px;padding:12px 17px}.dojo-metrics small{color:#796b56;font-size:13px}.dojo-metrics strong{display:block;font-size:29px}.dojo-metrics em{font-style:normal;font-weight:400;font-size:13px;margin-left:8px;color:#86745b}.dojo-panel{display:flex;flex-direction:column;flex:1;min-height:0;background:#fffcf7;border:1px solid #e0d5c3;border-radius:9px;padding:15px}.dojo-tabs{display:flex;align-items:center;gap:8px;flex:none;padding-bottom:12px;border-bottom:1px solid #e5dac9}.do